import{_ as e,o as t,c as n,a6 as s}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"封面、知识卡与出版配图","description":"","frontmatter":{"id":"content","title":"封面、知识卡与出版配图","chapter":"05","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":31,"content_kind":"任务入门"},"headers":[],"relativePath":"brand-content/content.md","filePath":"brand-content/content.md"}'),o={name:"brand-content/content.md"};function i(p,a,r,c,d,l){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="封面、知识卡与出版配图-先分文字与画面" tabindex="-1">封面、知识卡与出版配图，先分文字与画面 <a class="header-anchor" href="#封面、知识卡与出版配图-先分文字与画面" aria-label="Permalink to &quot;封面、知识卡与出版配图，先分文字与画面&quot;">​</a></h1><p>本节把一段“产品照片换场景”的说明改成封面和三张知识卡。做完应有准确文案、无字插图、可编辑排版和独立图片。真实案例正文缺证据时，先做方法说明，不能配一张假效果图当亲测结果。</p><h2 id="_1-从正文提取四张卡的职责" tabindex="-1">1. 从正文提取四张卡的职责 <a class="header-anchor" href="#_1-从正文提取四张卡的职责" aria-label="Permalink to &quot;1. 从正文提取四张卡的职责&quot;">​</a></h2><p>封面写读者任务“产品照片换场景”。卡1讲输入，需要真实商品照片；卡2讲做法，背景生成与主体合成；卡3讲检查，边缘、结构、文字和裁切。每张只留一句主标题和两三条必要说明。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把我提供的教程正文整理成一张封面和三张知识卡。保持原文的事实和执行状态，不增加成功率、效率、亲测经历或未提供的效果。</span></span>
<span class="line"><span>每张输出短标题、最多三条准确说明、需要的配图和布局。封面突出读者任务，三张分别讲输入、处理、检查。没有真实结果的地方标示方法示意，不伪装操作截图。文字输出为可编辑文案，不直接生成文字图片。</span></span></code></pre></div><h2 id="_2-让图像工具只做需要的插图" tabindex="-1">2. 让图像工具只做需要的插图 <a class="header-anchor" href="#_2-让图像工具只做需要的插图" aria-label="Permalink to &quot;2. 让图像工具只做需要的插图&quot;">​</a></h2><p>商品图类知识卡尽量用授权实拍和真实操作截图。需要示意插图时可用下面的词，画面明确是教学插图。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>绘制一张浅色教学插图，表达商品照片被放到新的厨房背景。使用简洁纸片与图层示意，产品只作为通用杯子轮廓，不表示某品牌真实效果。左侧输入、右侧环境，中间有合成动作的视觉关系，留出标题和说明文字区域。</span></span>
<span class="line"><span>画面简洁，奶油白、深灰和少量橙色，不生成文字、数字、Logo、水印或假软件界面。不制作虚假的前后实测对比。</span></span></code></pre></div><h2 id="_3-排版后读一次正文" tabindex="-1">3. 排版后读一次正文 <a class="header-anchor" href="#_3-排版后读一次正文" aria-label="Permalink to &quot;3. 排版后读一次正文&quot;">​</a></h2><p>用文字层加入标题与说明。三个步骤不要被装饰元素隔开，阅读顺序从上到下。出处、示意标签和执行状态放在能读的位置。缩到手机宽度逐字读，长句删到保留动作与结果；数字和方法不能为了好看而改。</p><p>出版配图另核实际版心、分辨率、颜色与许可，不把社交卡像素当印刷规定。完整词见<a href="./../prompts/P03">P03</a>，本节尚未制作和发布卡片。</p>`,11)])])}const u=e(o,[["render",i]]);export{_ as __pageData,u as default};
